#!/usr/bin/env python3
"""Offline R1 comparison router. Reuses W4 reference frames without copying them."""
from pathlib import Path
import json,hashlib
HERE=Path(__file__).resolve().parent
manifest=json.loads((HERE/'manifest.json').read_text())
data={'proposal':manifest['captures'],'references':[]}
for phase in ['before','after']:
 base=HERE.parent/'w4'/phase; old=json.loads((base/'manifest.json').read_text())
 for cap in old['captures']:
  if cap['engine']!='chromium' or cap['viewport'] not in ['1440x900','390x844']:continue
  stem=Path(cap['path']).stem
  if not any(stem.startswith(s) for s in ['black-sun','what-remains','protected-map','protected-people','protected-axiom']):continue
  p=base/cap['path'];assert hashlib.sha256(p.read_bytes()).hexdigest()==cap['sha256']
  data['references'].append({'phase':phase,'viewport':cap['viewport'],'file':'../w4/'+phase+'/'+cap['path'],'name':stem,'sha256':cap['sha256'],'sourceSha':old['sourceSha']})
(HERE/'reference-frame-manifest.json').write_text(json.dumps(data['references'],ensure_ascii=False,indent=2)+'\n')
encoded=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AXIOM / W4.R — BEFORE / CURRENT / PROPOSED</title><style>
*{box-sizing:border-box}body{margin:0;background:#080808;color:#ebebed;font:16px/1.6 system-ui,sans-serif}header{padding:30px 3%;border-top:3px solid #ff2034;border-bottom:1px solid #303138}h1{font-size:clamp(23px,3vw,40px);line-height:1.2;margin:0 0 14px}p{max-width:100ch;color:#bfc0c6}a{color:#ebebed}a:focus-visible,select:focus-visible{outline:2px solid #ff2034;outline-offset:4px}.controls{display:flex;flex-wrap:wrap;gap:20px;padding:25px 3%;border-bottom:1px solid #303138}label{display:grid;gap:7px;font-size:14px}select{padding:12px;background:#111214;color:#ebebed;border:1px solid #65656e;font:inherit;min-width:180px}.links{padding:14px 3%;display:flex;flex-wrap:wrap;gap:24px}.columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:25px 3%}.columns article{min-width:0}h2{font-size:20px;margin:0 0 12px}figure{margin:0 0 24px}img{display:block;width:100%;height:auto;border:1px solid #303138}figcaption{font-size:13px;color:#bfc0c6;padding-top:9px;overflow-wrap:anywhere}small{display:block;color:#bfc0c6;min-height:80px}#note{margin:0 3%;border-left:2px solid #ff2034;padding:12px 18px}.scope{padding:20px 3%;font-size:14px}@media(max-width:800px){.columns{grid-template-columns:1fr}small{min-height:0;margin-bottom:15px}.columns img{max-width:100%}select{max-width:90vw}}
</style></head><body><header><h1>AXIOM / W4.R<br>BEFORE · CURRENT · PROPOSED</h1><p><strong>R1 — выбор арт-дирекции. Gate R-A pending.</strong> Публичная страница не изменена. BEFORE —6b082e5, CURRENT — визуально отклонённый b85fbb0. PROPOSED — один из трёх самостоятельных макетов. Кадры Chromium/DPR1, без ретуши и склейки; нажмите кадр для просмотра в исходном размере.</p></header><div class="controls"><label>Направление<select id="concept"><option value="a">A / Палимпсест — рекомендация</option><option value="b">B / Линия разлома</option><option value="c">C / Камера свидетельств</option></select></label><label>Окно<select id="device"><option value="desktop">Desktop1440×900</option><option value="mobile">Mobile390×844</option></select></label><label>Сцена<select id="scene"><option value="archive">Архив — ключевой кадр</option><option value="doctrine">Доктрина — все сегменты</option><option value="remains">WHAT REMAINS — все сегменты</option><option value="geography">WORLD GRID — external intro</option><option value="people">CHARACTERS — external intro</option></select></label></div><div class="links"><a href="prototypes/a.html">Открыть живой макет A ↗</a><a href="prototypes/b.html">Макет B ↗</a><a href="prototypes/c.html">Макет C ↗</a><a href="../../waves/w4r/R0_R1_PROPOSAL.md">План / wireframes / tradeoffs</a><a href="../../waves/w4r/R0_VISUAL_ROOT_CAUSE.md">Root-cause audit</a><a href="../../waves/w4r/R0_TERMINOLOGY_TRACE.md">Canon trace</a></div><p id="note" aria-live="polite"></p><main class="columns"><article><h2>BEFORE /6b082e5</h2><small>Исходная сценография до W4. Содержание спорных чисел и подписи не предлагается возвращать.</small><div id="before"></div></article><article><h2>CURRENT /b85fbb0</h2><small>Отклонённый художественный результат. Runtime HEAD7413405 совпадает с этим freeze.</small><div id="after"></div></article><article><h2 id="proposed-title">PROPOSED</h2><small>R1 mockup. Новая режиссура и typography; не продуктовая интеграция и не R3 PASS.</small><div id="proposed"></div></article></main><noscript><p class="scope">Без JavaScript доступны три самостоятельных макета по ссылкам выше, manifest.json и исходные W4 пары. Для переключения сравнительных кадров используйте обычный браузер с JS.</p></noscript><footer class="scope">География/персонажи: старые native frames показывают protected сцену и могут иметь другой scroll position; это контекст сохранности, не новый точный pixel-diff внешнего заголовка. Полные исходные пары: <a href="../w4/REVIEW.html">W4 review</a>. Отдельный <a href="../w4/after/chromium/1440x900/protected-axiom.webp">AXIOM∅ — положительный эталон</a>. R2/R3/R4 не выполнены; все решения Gate R-A/R-B остаются за CREATOR.</footer><script id="data" type="application/json">'''+encoded+'''</script><script>
const data=JSON.parse(document.getElementById('data').textContent);function frame(src,text){const f=document.createElement('figure'),a=document.createElement('a'),img=document.createElement('img'),c=document.createElement('figcaption');a.href=src;a.target='_blank';a.rel='noopener';img.src=src;img.alt=text;img.loading='lazy';a.append(img);c.textContent=text;f.append(a,c);return f;}function render(){let concept=document.getElementById('concept').value,device=document.getElementById('device').value,scene=document.getElementById('scene').value,vp=device==='desktop'?'1440x900':'390x844';document.getElementById('proposed-title').textContent='PROPOSED /'+concept.toUpperCase();document.getElementById('note').textContent=scene==='archive'?'Ключевой кадр архива; на mobile он показывает часть высокой сцены. Выберите «Доктрина — все сегменты», чтобы прочитать четыре такта полностью.':scene==='geography'||scene==='people'?'PROPOSED показывает новое внешнее вступление. BEFORE/CURRENT — сохранённый native protected sample; разные scroll positions не выданы за равный pixel comparison.':'Все сохранённые viewport segments сцены. Последний кадр может включать начало следующей секции; кадры не обрезаны.';for(const phase of ['before','after']){let target=document.getElementById(phase);target.replaceChildren();let prefix=scene==='doctrine'?'black-sun':scene==='remains'?'what-remains':scene==='geography'?'protected-map':scene==='people'?'protected-people':'black-sun-2';let arr=data.references.filter(f=>f.phase===phase&&f.viewport===vp&&f.name.startsWith(prefix));for(const f of arr)target.append(frame(f.file,phase.toUpperCase()+' /'+f.sourceSha.slice(0,7)+' /'+vp+' /'+f.name));}let t=document.getElementById('proposed');t.replaceChildren();for(const f of data.proposal.filter(f=>f.concept===concept&&f.device===device&&f.scene===scene))t.append(frame('captures/'+f.file,'PROPOSED '+concept.toUpperCase()+' /'+vp+' /'+f.file));}for(const id of ['concept','device','scene'])document.getElementById(id).addEventListener('change',render);render();
</script></body></html>'''
(HERE/'REVIEW.html').write_text(html)
print('Review router built with',len(data['proposal']),'proposal frames and',len(data['references']),'verified reused reference frames.')
